actions.script:
const out = ec.service.sync().name('org.moqui.comms.InboxServices.run#Operation').parameters({operation: 'get#ComposeData', parameters: {emailMessageId: emailMessageId || null,
    replyToEmailMessageId: replyToEmailMessageId || null, forwardEmailMessageId: forwardEmailMessageId || null,
    replyAll: String(replyAll) === 'true', replyToCommEventId: replyToCommEventId || null, replyToSender: String(replyToSender) === 'true',
    contactListId: contactListId || null, to: to || null, cc: cc || null, bcc: bcc || null, subject: subject || null, body: body || null,
    recordEntity: recordEntity || null, recordId: recordId || null}}).call()?.result || {}
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {compose: out.compose})

const out = ec.service.sync().name('org.moqui.comms.InboxServices.run#Operation').parameters({operation: 'save#ComposeDraft', parameters: {emailMessageId: emailMessageId || null,
    fromValue: fromValue || '', toJson: toJson || '[]', ccJson: ccJson || '[]', bccJson: bccJson || '[]', subject: subject ?? '', body: body ?? '',
    bodyText: bodyText || null, quoteHtml: quoteHtml || null, parentEmailMessageId: parentEmailMessageId || null,
    isForward: String(isForward) === 'true', clientRef: clientRef || null}}).call()?.result || {}
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {emailMessageId: out.emailMessageId, rootEmailMessageId: out.rootEmailMessageId,
    duplicate: out.duplicate === true})

// the same for every app: a draft's files, or the user's own uploads for an app's message (send#Compose takes them)
const out = ec.service.sync().name('org.moqui.comms.ComposeServices.upload#ComposeAttachment').parameters({emailMessageId: emailMessageId || null,
    clientRef: clientRef || null, contentFile: contentFile || null}).call() || {}
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {attachmentList: out.attachmentList, uploadList: out.uploadList})

let items = []
try { items = JSON.parse(itemsJson || '[]') } catch (err) { items = [] }
const out = ec.service.sync().name('org.moqui.comms.InboxServices.run#Operation').parameters({operation: 'attach#DriveFiles', parameters: {emailMessageId: emailMessageId || null, itemList: items}}).call()?.result || {}
if (ec.message.hasError()) { ec.web.sendJsonResponse({}); return }
const infos = []
for (const failed of Array.from(out.failedList || [])) infos.push({type: 'warning', message: failed.name + ': ' + failed.error})
if (Array.from(out.linkList || []).length) infos.push({type: 'info', message: ec.l10n.localize('Too large to attach: a link to it is in the message')})
ec.web.sendJsonResponse({attachmentList: out.attachmentList, uploadList: out.uploadList, linkList: out.linkList, messageInfos: infos})

const out = ec.service.sync().name('org.moqui.comms.InboxServices.run#Operation').parameters({operation: 'remove#ComposeAttachment', parameters: {emailMessageId: emailMessageId || '',
    emailMessageAttachmentId: emailMessageAttachmentId || ''}}).call()?.result || {}
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {attachmentList: out.attachmentList})

const out = ec.service.sync().name('org.moqui.comms.InboxServices.run#Operation').parameters({operation: 'cancel#ComposeSend', parameters: {emailMessageId: emailMessageId || null,
    communicationEventIdsJson: communicationEventIdsJson || null}}).call()?.result || {}
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {statusId: out.statusId})
